-- Every city is a Crown city, and the Hot Zone can be any of them.
--  * A table of the world's cities (2932 of them — every one over 150,000 people), each with a radius that grows
--    with its size. Which city a plot is in is now the nearest one whose radius it's inside, anywhere on Earth.
--  * The Crown: one per city, for all of them (not just the 28 Hot Zone cities). Crowns are keyed by city id (two cities
--    can share a name).
--  * The Hot Zone: a different random city every day, picked from all of them.
create table if not exists public.world_cities (
  id int primary key,
  name text not null,
  country text not null,
  gx int not null,
  gy int not null,
  pop int not null,
  radius int not null
);
create index if not exists world_cities_gx_gy on public.world_cities (gx, gy);
-- (ids run 1…n with no gaps: the Hot Zone picks one by id)
alter table public.world_cities enable row level security;
revoke all on public.world_cities from anon, authenticated;

on conflict (id) do update set name = excluded.name, country = excluded.country, gx = excluded.gx, gy = excluded.gy, pop = excluded.pop, radius = excluded.radius;

-- which city a cell is in: the nearest (relative to its size) whose radius covers it
create or replace function private.city_at(p_gx int, p_gy int) returns jsonb language sql stable as $$
  select jsonb_build_object('id', c.id::text, 'name', c.name, 'country', c.country, 'gx', c.gx, 'gy', c.gy, 'radius', c.radius)
  from public.world_cities c
  where c.gx between p_gx - 2500 and p_gx + 2500 and c.gy between p_gy - 2500 and p_gy + 2500
    and ((p_gx - c.gx)::numeric ^ 2 + (p_gy - c.gy)::numeric ^ 2) <= (c.radius::numeric ^ 2)
  order by ((p_gx - c.gx)::numeric ^ 2 + (p_gy - c.gy)::numeric ^ 2) / (c.radius::numeric ^ 2), c.id
  limit 1
$$;
-- (p_city is a city id now)
create or replace function private.crown_held(p_city text) returns boolean language sql stable as $$
  select exists (select 1 from public.world_plots p where p.rarity = 'crown' and p.owner_id is not null and private.city_at(p.gx, p.gy) ->> 'id' = p_city)
$$;

-- the Hot Zone: a random city every day, any city in the world
create or replace function private.hot_zone(p_day date) returns jsonb language sql stable as $$
  select case when coalesce((z ->> 'enabled')::boolean, true) then (
    select jsonb_build_object('id', c.id::text, 'name', c.name, 'country', c.country, 'gx', c.gx, 'gy', c.gy,
                              'radius', coalesce((z ->> 'radius')::int, 2500), 'day', p_day)
    from public.world_cities c
    where c.id = 1 + abs(hashtext('hot-zone:' || p_day::text)::bigint) % (select max(id) from public.world_cities)) end
  from (select private.cfg('hot_zones') z) x
$$;

do $$
declare d text; n text;
begin
  d := pg_get_functiondef('private.plot_rarity_for(integer,integer)'::regprocedure);
  n := replace(d, $a$private.crown_held(v_city ->> 'name')$a$, $a$private.crown_held(v_city ->> 'id')$a$);
  if n = d then raise exception 'world cities: plot_rarity_for anchor not found'; end if; execute n;

  d := pg_get_functiondef('private.take_plot(uuid,integer,integer,text,jsonb)'::regprocedure);
  n := replace(d, $a$private.city_at(p_gx, p_gy) ->> 'name'$a$, $a$private.city_at(p_gx, p_gy) ->> 'id'$a$);
  if n = d then raise exception 'world cities: take_plot anchor not found'; end if; execute n;

  d := pg_get_functiondef('public.hot_zone_today()'::regprocedure);
  n := replace(d, $a$private.crown_held(private.hot_zone(private.today()) ->> 'name')$a$, $a$private.crown_held(private.hot_zone(private.today()) ->> 'id')$a$);
  if n = d then raise exception 'world cities: hot_zone_today anchor not found'; end if; execute n;
end $$;

-- the Crowns of the world: how many cities there are, and every Crown that's been claimed
drop function if exists public.crowns();
create function public.crowns() returns jsonb language sql stable security definer set search_path = public, pg_temp as $$
  select jsonb_build_object('total', (select count(*) from public.world_cities),
    'held', coalesce((select jsonb_agg(jsonb_build_object('city', x.c ->> 'name', 'country', x.c ->> 'country', 'holder', x.holder, 'since', x.claimed_at) order by x.claimed_at desc)
      from (select private.city_at(p.gx, p.gy) c, pr.username holder, p.claimed_at
              from public.world_plots p join public.profiles pr on pr.id = p.owner_id
             where p.rarity = 'crown' and p.owner_id is not null) x where x.c is not null), '[]'::jsonb))
$$;
revoke all on function public.crowns() from public, anon;
grant execute on function public.crowns() to authenticated;
revoke all on function private.city_at(integer, integer) from public, anon, authenticated;
revoke all on function private.crown_held(text) from public, anon, authenticated;
revoke all on function private.hot_zone(date) from public, anon, authenticated;
